export function buildModel(data) {
  const alias = new Map()
  data.commits.forEach((c) => c.files.forEach((f) => f.old && alias.set(f.old, f.path)))
  const resolve = (path) => {
    for (let hops = 0; alias.has(path) && hops < 20; hops++) path = alias.get(path)
    return path
  }

  const entries = new Map()
  const ensure = (path) => {
    if (!entries.has(path)) {
      entries.set(path, { path, cur: null, events: [], deleted: false })
    }
    return entries.get(path)
  }
  data.files.forEach((f) => (ensure(f.path).cur = f))
  data.commits.forEach((c, idx) =>
    c.files.forEach((f) =>
      ensure(resolve(f.path)).events.push({ commit: idx, add: f.add, del: f.del, isNew: f.status === 'added', patch: f }),
    ),
  )

  const count = data.commits.length
  const files = [...entries.values()].map((e) => {
    e.deleted = !e.cur
    e.lang = e.cur?.lang ?? 'text'
    e.dir = e.path.includes('/') ? e.path.slice(0, e.path.lastIndexOf('/')) : ''
    e.name = e.path.slice(e.path.lastIndexOf('/') + 1)
    e.binary = !!e.cur && (e.cur.binary ?? e.cur.text === null)
    const added = e.events.find((ev) => ev.isNew)
    const fallback = data.truncated ? -1 : e.events.length ? e.events[0].commit : count
    e.firstCommit = added ? added.commit : fallback
    const delta = (k) => e.events.filter((ev) => ev.commit === k).reduce((s, ev) => s + ev.add - ev.del, 0)
    e.locAt = new Array(count + 1).fill(0)
    if (e.cur) {
      let loc = e.cur.loc
      e.locAt[count] = loc
      for (let k = count - 1; k >= 0; k--) {
        e.locAt[k] = Math.max(0, loc)
        loc -= delta(k)
      }
    } else {
      let running = 0
      for (let k = 0; k < count; k++) {
        running += delta(k)
        e.locAt[k] = Math.max(0, running)
      }
    }
    e.maxLoc = Math.max(1, ...e.locAt)
    return e
  })
  files.sort((a, b) => a.path.localeCompare(b.path))
  files.forEach((f, i) => (f.index = i))
  return { data, files, count, commits: data.commits, byPath: new Map(files.map((f) => [f.path, f])) }
}

export function existsAt(f, k, count) {
  if (k >= count) return !!f.cur
  if (f.firstCommit > k) return false
  return f.locAt[k] > 0 || f.binary
}

export function stateAt(f, k, count) {
  if (k >= count) {
    if (!f.cur) return 'gone'
    return f.cur.status === 'clean' ? 'clean' : f.cur.status
  }
  const hits = f.events.filter((ev) => ev.commit === k)
  if (!hits.length) return existsAt(f, k, count) ? 'clean' : 'gone'
  if (f.firstCommit === k) return 'added'
  return f.locAt[k] === 0 && !f.binary ? 'deleted' : 'modified'
}

export function locAt(f, k, count) {
  const loc = f.locAt[Math.min(k, count)]
  return f.binary ? 1 : loc
}

function weight(f) {
  return Math.pow(Math.max(f.maxLoc, 8), 0.7)
}

export function buildTree(files) {
  const root = { name: '', path: '', depth: 0, children: new Map(), files: [] }
  files.forEach((f) => {
    let node = root
    f.dir
      .split('/')
      .filter(Boolean)
      .forEach((part) => {
        if (!node.children.has(part)) {
          const path = node.path ? `${node.path}/${part}` : part
          node.children.set(part, { name: part, path, depth: node.depth + 1, children: new Map(), files: [] })
        }
        node = node.children.get(part)
      })
    node.files.push(f)
  })
  return root
}

export function layoutCity(files) {
  const root = buildTree(files)

  const total = (node) =>
    node.files.reduce((s, f) => s + weight(f), 0) + [...node.children.values()].reduce((s, c) => s + total(c), 0)

  const districts = []
  const place = (node, path, x, z, w, d, depth) => {
    const items = [
      ...node.files.map((f) => ({ file: f, w: weight(f) })),
      ...[...node.children.values()].map((c) => ({ node: c, w: total(c) })),
    ].sort((a, b) => b.w - a.w)
    const sum = items.reduce((s, i) => s + i.w, 0) || 1
    if (path) districts.push({ path, name: node.name, x: x + w / 2, z: z + d / 2, w, d, depth })

    const pad = Math.min(1.1, Math.min(w, d) * 0.08)
    slice(items, sum, x + pad, z + pad, w - pad * 2, d - pad * 2, depth, path)
  }
  const slice = (items, sum, x, z, w, d, depth, path) => {
    if (!items.length) return
    if (items.length === 1) return cell(items[0], x, z, w, d, depth, path)
    const half = sum / 2
    let acc = 0
    let split = 0
    while (split < items.length - 1 && acc + items[split].w <= half) acc += items[split++].w
    split = Math.max(1, split)
    const left = items.slice(0, split)
    const right = items.slice(split)
    const leftSum = left.reduce((s, i) => s + i.w, 0)
    const ratio = leftSum / sum
    if (w >= d) {
      slice(left, leftSum, x, z, w * ratio, d, depth, path)
      slice(right, sum - leftSum, x + w * ratio, z, w * (1 - ratio), d, depth, path)
    } else {
      slice(left, leftSum, x, z, w, d * ratio, depth, path)
      slice(right, sum - leftSum, x, z + d * ratio, w, d * (1 - ratio), depth, path)
    }
  }
  const cell = (item, x, z, w, d, depth, path) => {
    if (item.file) {
      item.file.pos = { x: x + w / 2, z: z + d / 2, w: Math.max(0.5, w * 0.78), d: Math.max(0.5, d * 0.78) }
    } else {
      place(item.node, path ? `${path}/${item.node.name}` : item.node.name, x, z, w, d, depth + 1)
    }
  }

  const side = Math.max(48, Math.sqrt(total(root)) * 2.4)
  place(root, '', -side / 2, -side / 2, side, side, 0)
  return { districts, size: side, tree: root }
}

export function layoutGraph(files) {
  let seed = 7
  const rand = () => ((seed = (seed * 16807) % 2147483647) / 2147483647) - 0.5
  const nodes = files.map((f) => ({
    f,
    x: (f.pos?.x ?? 0) * 0.8 + rand() * 4,
    y: rand() * 20,
    z: (f.pos?.z ?? 0) * 0.8 + rand() * 4,
    vx: 0,
    vy: 0,
    vz: 0,
  }))
  const byPath = new Map(nodes.map((n) => [n.f.path, n]))
  const edges = files.flatMap((f) =>
    (f.cur?.imports ?? []).filter((p) => byPath.has(p)).map((p) => [byPath.get(f.path), byPath.get(p)]),
  )
  const degree = new Map()
  edges.forEach(([a, b]) => {
    degree.set(a, (degree.get(a) ?? 0) + 1)
    degree.set(b, (degree.get(b) ?? 0) + 1)
  })

  for (let iter = 0; iter < 400; iter++) {
    const cool = 1 - iter / 400
    nodes.forEach((a, i) => {
      for (let j = i + 1; j < nodes.length; j++) {
        const b = nodes[j]
        const dx = a.x - b.x
        const dy = a.y - b.y
        const dz = a.z - b.z
        const d2 = dx * dx + dy * dy + dz * dz + 0.5
        const force = 60 / d2
        const d = Math.sqrt(d2)
        a.vx += (dx / d) * force
        a.vy += (dy / d) * force
        a.vz += (dz / d) * force
        b.vx -= (dx / d) * force
        b.vy -= (dy / d) * force
        b.vz -= (dz / d) * force
      }
    })
    edges.forEach(([a, b]) => {
      const dx = b.x - a.x
      const dy = b.y - a.y
      const dz = b.z - a.z
      const d = Math.sqrt(dx * dx + dy * dy + dz * dz) + 0.01
      const pull = (d - 7) * 0.04
      a.vx += (dx / d) * pull
      a.vy += (dy / d) * pull
      a.vz += (dz / d) * pull
      b.vx -= (dx / d) * pull
      b.vy -= (dy / d) * pull
      b.vz -= (dz / d) * pull
    })
    nodes.forEach((n) => {
      const orphan = !degree.has(n)
      n.vx -= n.x * (orphan ? 0.05 : 0.004)
      n.vy -= n.y * 0.01
      n.vz -= n.z * (orphan ? 0.05 : 0.004)
      n.x += n.vx * 0.5 * cool
      n.y += n.vy * 0.5 * cool
      n.z += n.vz * 0.5 * cool
      n.vx *= 0.6
      n.vy *= 0.6
      n.vz *= 0.6
    })
  }
  nodes.forEach((n) => (n.f.graphPos = { x: n.x, y: n.y + 12, z: n.z }))
  return { edges: edges.map(([a, b]) => [a.f, b.f]) }
}

// Builds the "send feedback" link: a prefilled new-issue page on GitHub. Nothing is sent from the
// app. The link opens in a new tab and the user submits it under their own GitHub account, so
// there is no token, no API call and no CSP change.

// The one place the issue tracker is named. Change it if the repository moves or is renamed.
export const FEEDBACK_REPO = 'joellithgow95/codemap'

// Applied by GitHub only if the label already exists; .github/workflows/labels.yml creates them.
const LABELS = ['feedback', 'from-app']

const MAX_URL = 7000
const MAX_NAME = 100

// `context` is { version, view, camera, lens, repo?, userAgent }. Pass `repo` only for a public
// map (a bundled demo, or a GitHub load made without a token): it lands in a URL that the user may
// share, so a private repo's name must never get here.
export function feedbackUrl(context) {
  const title = 'Feedback: '
  const head = '### What happened / what I expected\n\n\n\n### Steps to reproduce (if it is a bug)\n\n\n\n### Context\n'
  const fields = [
    ['App version', context.version],
    ['View', context.view],
    ['Camera', context.camera],
    ['Lens', context.lens],
    ['Map', context.repo && String(context.repo).slice(0, MAX_NAME)],
    ['Browser', context.userAgent],
  ].filter(([, value]) => value)
  const build = (count) =>
    `https://github.com/${FEEDBACK_REPO}/issues/new?` +
    new URLSearchParams({ title, labels: LABELS.join(','), body: head + fields.slice(0, count).map(([k, v]) => `- ${k}: ${v}`).join('\n') + '\n' })
  // Drop context from the end (the long user agent first) until the URL fits.
  let count = fields.length
  let url = build(count)
  while (url.length > MAX_URL && count > 0) url = build(--count)
  return url
}

// Read-only access to a repo's .git folder from the browser: HEAD, refs, loose objects and
// packfiles with their delta chains. Inflation uses the native DecompressionStream, so there are no
// dependencies and nothing leaves the tab. `folder` is a local.js folder: file(path), list(path).

const TYPES = { 1: 'commit', 2: 'tree', 3: 'blob', 4: 'tag' }
const OFS_DELTA = 6
const REF_DELTA = 7
const IDX_MAGIC = 0xff744f63
const PACK_TRAILER_BYTES = 20
const CACHE_LIMIT = 256
export const TREE_MODE = '40000'
export const GITLINK_MODE = '160000'

const decoder = new TextDecoder()

export const toHex = (bytes) => Array.from(bytes, (b) => b.toString(16).padStart(2, '0')).join('')
const fromHex = (hex) => Uint8Array.from(hex.match(/../g), (h) => parseInt(h, 16))

async function inflate(bytes) {
  const stream = new Blob([bytes]).stream().pipeThrough(new DecompressionStream('deflate'))
  return new Uint8Array(await new Response(stream).arrayBuffer())
}

async function readText(folder, path) {
  const file = await folder.file(path)
  return file ? file.text() : null
}

function compareSha(table, at, sha) {
  for (let i = 0; i < 20; i++) {
    const diff = table[at + i] - sha[i]
    if (diff) return diff
  }
  return 0
}

// A pack is located through its v2 .idx: a fan-out table, the sorted object ids, then each
// object's offset. An object's bytes run from its offset to the next object's (or the trailer).
async function openPack(folder, base) {
  const idx = new Uint8Array(await (await folder.file(`${base}.idx`)).arrayBuffer())
  const pack = await folder.file(`${base}.pack`)
  const view = new DataView(idx.buffer)
  if (!pack || view.getUint32(0) !== IDX_MAGIC || view.getUint32(4) !== 2) return null

  const count = view.getUint32(8 + 255 * 4)
  const shaStart = 8 + 256 * 4
  const offsetStart = shaStart + count * 24
  const bigStart = offsetStart + count * 4
  const offsetAt = (i) => {
    const raw = view.getUint32(offsetStart + i * 4)
    if (!(raw & 0x80000000)) return raw
    const big = bigStart + (raw & 0x7fffffff) * 8
    return view.getUint32(big) * 2 ** 32 + view.getUint32(big + 4)
  }
  const sorted = Float64Array.from({ length: count }, (_, i) => offsetAt(i)).sort()

  const find = (sha) => {
    let lo = sha[0] ? view.getUint32(8 + (sha[0] - 1) * 4) : 0
    let hi = view.getUint32(8 + sha[0] * 4)
    while (lo < hi) {
      const mid = (lo + hi) >> 1
      const cmp = compareSha(idx, shaStart + mid * 20, sha)
      if (!cmp) return offsetAt(mid)
      if (cmp < 0) lo = mid + 1
      else hi = mid
    }
    return null
  }
  const endOf = (offset) => {
    let lo = 0
    let hi = count
    while (lo < hi) {
      const mid = (lo + hi) >> 1
      if (sorted[mid] <= offset) lo = mid + 1
      else hi = mid
    }
    return lo < count ? sorted[lo] : pack.size - PACK_TRAILER_BYTES
  }

  const rawAt = async (offset) => {
    const bytes = new Uint8Array(await pack.slice(offset, endOf(offset)).arrayBuffer())
    let i = 0
    let c = bytes[i++]
    const type = (c >> 4) & 7
    while (c & 0x80) c = bytes[i++]
    let base = null
    if (type === OFS_DELTA) {
      c = bytes[i++]
      let back = c & 0x7f
      while (c & 0x80) {
        c = bytes[i++]
        back = (back + 1) * 128 + (c & 0x7f)
      }
      base = { offset: offset - back }
    } else if (type === REF_DELTA) {
      base = { sha: toHex(bytes.subarray(i, i + 20)) }
      i += 20
    }
    return { type, base, data: await inflate(bytes.subarray(i)) }
  }
  return { find, rawAt }
}

// A delta is the target size, then copy-from-base and insert-literal instructions.
function applyDelta(base, delta) {
  let i = 0
  const varint = () => {
    let n = 0
    let scale = 1
    let c
    do {
      c = delta[i++]
      n += (c & 0x7f) * scale
      scale *= 128
    } while (c & 0x80)
    return n
  }
  varint()
  const out = new Uint8Array(varint())
  let o = 0
  while (i < delta.length) {
    const op = delta[i++]
    if (op & 0x80) {
      let offset = 0
      let size = 0
      for (let b = 0; b < 4; b++) if (op & (1 << b)) offset += delta[i++] * 2 ** (8 * b)
      for (let b = 0; b < 3; b++) if (op & (0x10 << b)) size += delta[i++] * 2 ** (8 * b)
      size ||= 0x10000
      out.set(base.subarray(offset, offset + size), o)
      o += size
    } else {
      out.set(delta.subarray(i, i + op), o)
      o += op
      i += op
    }
  }
  return out
}

async function resolveHead(folder) {
  const head = (await readText(folder, '.git/HEAD'))?.trim()
  if (!head) return null
  if (!head.startsWith('ref: ')) return { branch: '(detached)', sha: head }

  const ref = head.slice(5)
  const branch = ref.replace(/^refs\/heads\//, '')
  const loose = await readText(folder, `.git/${ref}`)
  if (loose) return { branch, sha: loose.trim() }
  const packed = (await readText(folder, '.git/packed-refs')) ?? ''
  const line = packed.split('\n').find((l) => l.endsWith(` ${ref}`))
  return { branch, sha: line ? line.split(' ')[0] : null }
}

// Returns null when the folder has no readable .git: not a repo, or a worktree/submodule whose
// .git is a pointer file to a directory outside the folder that was picked.
export async function openGit(folder) {
  const head = await resolveHead(folder)
  if (!head) return null

  const packDir = '.git/objects/pack'
  const packNames = (await folder.list(packDir)).filter((e) => e.name.endsWith('.idx'))
  const packs = (await Promise.all(packNames.map((e) => openPack(folder, `${packDir}/${e.name.slice(0, -4)}`)))).filter(Boolean)

  const cache = new Map()
  const remember = (key, obj) => {
    cache.set(key, obj)
    if (cache.size > CACHE_LIMIT) cache.delete(cache.keys().next().value)
    return obj
  }

  const fromPack = async (pack, packIndex, offset) => {
    const key = `${packIndex}:${offset}`
    if (cache.has(key)) return cache.get(key)
    const raw = await pack.rawAt(offset)
    let obj
    if (raw.type === OFS_DELTA) {
      const base = await fromPack(pack, packIndex, raw.base.offset)
      obj = { type: base.type, data: applyDelta(base.data, raw.data) }
    } else if (raw.type === REF_DELTA) {
      const base = await read(raw.base.sha)
      obj = { type: base.type, data: applyDelta(base.data, raw.data) }
    } else {
      obj = { type: TYPES[raw.type], data: raw.data }
    }
    return remember(key, obj)
  }

  const read = async (sha) => {
    const id = fromHex(sha)
    for (const [packIndex, pack] of packs.entries()) {
      const offset = pack.find(id)
      if (offset !== null) return fromPack(pack, packIndex, offset)
    }
    if (cache.has(sha)) return cache.get(sha)
    const loose = await folder.file(`.git/objects/${sha.slice(0, 2)}/${sha.slice(2)}`)
    if (!loose) throw new Error(`git object ${sha} not found`)
    const data = await inflate(new Uint8Array(await loose.arrayBuffer()))
    const nul = data.indexOf(0)
    const type = decoder.decode(data.subarray(0, nul)).split(' ')[0]
    return remember(sha, { type, data: data.subarray(nul + 1) })
  }

  return {
    branch: head.branch,
    head: head.sha,
    read,
    commit: async (sha) => parseCommit((await read(sha)).data),
    tree: async (sha) => parseTree((await read(sha)).data),
  }
}

function parseCommit(data) {
  const text = decoder.decode(data)
  const split = text.indexOf('\n\n')
  const header = split < 0 ? text : text.slice(0, split)
  const lines = header.split('\n')
  const author = /^author (.*) <[^>]*> (\d+)/m.exec(header)
  return {
    tree: lines.find((l) => l.startsWith('tree ')).slice(5),
    parents: lines.filter((l) => l.startsWith('parent ')).map((l) => l.slice(7)),
    author: author?.[1] ?? 'unknown',
    date: author ? new Date(Number(author[2]) * 1000).toISOString() : '',
    subject: split < 0 ? '' : text.slice(split + 2).split('\n')[0],
  }
}

function parseTree(data) {
  const entries = []
  let i = 0
  while (i < data.length) {
    const space = data.indexOf(0x20, i)
    const nul = data.indexOf(0, space)
    entries.push({
      mode: decoder.decode(data.subarray(i, space)),
      name: decoder.decode(data.subarray(space + 1, nul)),
      sha: toHex(data.subarray(nul + 1, nul + 21)),
    })
    i = nul + 21
  }
  return entries
}

import {
  BINARY_EXT,
  DATA_EXT,
  MAX_PATCH_LINES,
  MAX_TEXT_BYTES,
  MAX_TREE_FILES,
  buildResolver,
  countLines,
  extractImports,
  extractSymbols,
  langOf,
  parsesSymbols,
  pool,
  wantsText,
} from './parse.js'

const API = 'https://api.github.com'
const RAW = 'https://raw.githubusercontent.com'
const MAX_TEXT_FILES = 500

export class GithubError extends Error {}

export function parseRepoSpec(input) {
  const text = input.trim().replace(/\.git$/, '').replace(/\/$/, '')
  const url = /github\.com[/:]([^/\s]+)\/([^/\s#?]+)(?:\/tree\/([^\s#?]+)|\/pull\/(\d+))?/.exec(text)
  if (url) return { owner: url[1], repo: url[2], ref: url[3] ?? null, pull: url[4] ? Number(url[4]) : null }
  const short = /^([\w.-]+)\/([\w.-]+?)(?:@(.+)|#(\d+))?$/.exec(text)
  if (short) return { owner: short[1], repo: short[2], ref: short[3] ?? null, pull: short[4] ? Number(short[4]) : null }
  throw new GithubError(`Can't read "${input}" as a GitHub repo. Use owner/name or a github.com URL.`)
}

function authHeaders(token) {
  const headers = { Accept: 'application/vnd.github+json' }
  if (token) headers.Authorization = `Bearer ${token}`
  return headers
}

async function api(ctx, path) {
  const res = await fetch(`${API}${path}`, { headers: authHeaders(ctx.token) })
  const remaining = res.headers.get('x-ratelimit-remaining')
  if (remaining !== null) ctx.remaining = Number(remaining)
  if (res.ok) return res.json()
  if ((res.status === 403 || res.status === 429) && ctx.remaining === 0) {
    const reset = new Date(Number(res.headers.get('x-ratelimit-reset')) * 1000)
    throw new GithubError(
      `GitHub API rate limit hit (resets ${reset.toLocaleTimeString()}). Add a token in the menu for 5,000 requests/hour.`,
    )
  }
  if (res.status === 404) {
    throw new GithubError(
      ctx.token
        ? `${ctx.owner}/${ctx.repo} not found, or your token can't read it.`
        : `${ctx.owner}/${ctx.repo} not found. Private repo? Add a token in the menu.`,
    )
  }
  if (res.status === 401) throw new GithubError('GitHub rejected that token (401).')
  throw new GithubError(`GitHub API ${res.status} for ${path}`)
}

function decodeBase64(b64) {
  const bin = atob(b64.replace(/\n/g, ''))
  return new TextDecoder().decode(Uint8Array.from(bin, (c) => c.charCodeAt(0)))
}

export async function fetchText(ctx, entry) {
  if (ctx.token) {
    const blob = await api(ctx, `/repos/${ctx.owner}/${ctx.repo}/git/blobs/${entry.sha}`)
    return decodeBase64(blob.content)
  }
  const res = await fetch(`${RAW}/${ctx.owner}/${ctx.repo}/${ctx.commit}/${entry.path.split('/').map(encodeURIComponent).join('/')}`)
  if (!res.ok) throw new GithubError(`raw fetch ${res.status} for ${entry.path}`)
  return res.text()
}

function textPriority(entry) {
  const lang = langOf(entry.path)
  return (parsesSymbols(lang) ? 0 : lang === 'text' ? 3 : 1) * 1e7 + entry.size
}

function toCommitEntry(raw) {
  return {
    sha: raw.sha,
    short: raw.sha.slice(0, 7),
    author: raw.commit.author?.name ?? raw.author?.login ?? 'unknown',
    date: raw.commit.author?.date ?? '',
    subject: raw.commit.message.split('\n')[0],
    files: [],
  }
}

function toCommitFile(f) {
  const patch = (f.patch ?? '').split('\n')
  return {
    path: f.filename,
    old: f.status === 'renamed' ? f.previous_filename : null,
    add: f.additions,
    del: f.deletions,
    status: f.status,
    patch: patch.slice(0, MAX_PATCH_LINES).join('\n'),
    truncated: patch.length > MAX_PATCH_LINES,
  }
}

// Open PRs, newest activity first. One page is enough for a picker.
export async function listPulls(spec, token = '') {
  const ctx = { owner: spec.owner, repo: spec.repo, token, remaining: null }
  const pulls = await api(ctx, `/repos/${ctx.owner}/${ctx.repo}/pulls?state=open&sort=updated&per_page=30`)
  return pulls.map((p) => ({ number: p.number, title: p.title, author: p.user?.login ?? 'unknown', draft: p.draft, updated: p.updated_at }))
}

export async function loadGithub(spec, { token = '', commitLimit = 50, onProgress = () => {} } = {}) {
  const ctx = { owner: spec.owner, repo: spec.repo, token, remaining: null, commit: null }

  onProgress('repository', 0, 1)
  const meta = await api(ctx, `/repos/${ctx.owner}/${ctx.repo}`)
  let ref = spec.ref ?? meta.default_branch

  // A PR is mapped as its own commits over the tree at its head, so stepping
  // through history shows what the PR changes. The API caps this endpoint at 250 commits.
  let pull = null
  let listed
  if (spec.pull) {
    onProgress('pull request', 0, 1)
    const pr = await api(ctx, `/repos/${ctx.owner}/${ctx.repo}/pulls/${spec.pull}`)
    pull = { number: pr.number, title: pr.title, state: pr.merged ? 'merged' : pr.state, base: pr.base.ref, head: pr.head.label }
    ref = `PR #${pr.number}`
    listed = (await api(ctx, `/repos/${ctx.owner}/${ctx.repo}/pulls/${pr.number}/commits?per_page=100`)).reverse().slice(0, commitLimit)
    if (!listed.length) throw new GithubError(`PR #${pr.number} has no commits.`)
  } else {
    onProgress('commit list', 0, 1)
    listed = await api(ctx, `/repos/${ctx.owner}/${ctx.repo}/commits?sha=${encodeURIComponent(ref)}&per_page=${Math.min(commitLimit, 100)}`)
    if (!listed.length) throw new GithubError(`${ctx.owner}/${ctx.repo} has no commits on ${ref}.`)
  }
  ctx.commit = listed[0].sha

  onProgress('file tree', 0, 1)
  const tree = await api(ctx, `/repos/${ctx.owner}/${ctx.repo}/git/trees/${ctx.commit}?recursive=1`)
  const blobs = tree.tree.filter((n) => n.type === 'blob').map((n) => ({ path: n.path, size: n.size ?? 0, sha: n.sha }))
  const keptBlobs = blobs.slice(0, MAX_TREE_FILES)

  const commits = listed.map(toCommitEntry).reverse()
  const details = await pool(commits, 6, async (commit, i) => {
    const detail = await api(ctx, `/repos/${ctx.owner}/${ctx.repo}/commits/${commit.sha}`)
    onProgress('commit diffs', i + 1, commits.length)
    return detail.files ?? []
  })
  commits.forEach((c, i) => (c.files = details[i].map(toCommitFile)))

  const textTargets = keptBlobs
    .filter(wantsText)
    .sort((a, b) => textPriority(a) - textPriority(b))
    .slice(0, MAX_TEXT_FILES)
  let loaded = 0
  const texts = new Map()
  await pool(textTargets, 8, async (entry) => {
    try {
      texts.set(entry.path, await fetchText(ctx, entry))
    } catch {
      texts.set(entry.path, null)
    }
    onProgress('file contents', ++loaded, textTargets.length)
  })

  const resolver = buildResolver(keptBlobs.map((b) => b.path))
  const authors = new Map()
  const touched = new Map()
  commits.forEach((c, idx) =>
    c.files.forEach((f) => {
      const key = f.path
      if (!touched.has(key)) touched.set(key, [])
      touched.get(key).push(idx)
      if (!authors.has(key)) authors.set(key, new Set())
      authors.get(key).add(c.author)
    }),
  )

  const files = keptBlobs.map((b) => {
    const lang = langOf(b.path)
    const text = texts.get(b.path) ?? null
    const binary = BINARY_EXT.test(b.path) || (!wantsText(b) && b.size > MAX_TEXT_BYTES) || (text === null && DATA_EXT.test(b.path))
    return {
      path: b.path,
      sha: b.sha,
      lang,
      loc: text !== null ? countLines(text) : binary ? 0 : Math.max(1, Math.ceil(b.size / 36)),
      bytes: b.size,
      text,
      binary,
      remote: true,
      symbols: text && parsesSymbols(lang) ? extractSymbols(text, lang) : [],
      imports: text ? extractImports(text, lang, b.path, resolver) : [],
      commits: touched.get(b.path) ?? [],
      added: 0,
      deleted: 0,
      authors: [...(authors.get(b.path) ?? [])].sort(),
      tracked: true,
      status: 'clean',
      dirtyLines: [],
      blame: [],
    }
  })

  const doc = {
    repo: ctx.repo,
    head: ctx.commit.slice(0, 7),
    branch: ref,
    generated: new Date().toISOString(),
    source: 'github',
    owner: ctx.owner,
    truncated: !pull && listed.length >= commitLimit,
    ...(pull && { pull }),
    treeTruncated: tree.truncated || blobs.length > MAX_TREE_FILES,
    commits,
    files,
  }
  return { doc, ctx }
}

const KEYWORDS = {
  python: 'and as assert async await break class continue def del elif else except finally for from global if import in is lambda None nonlocal not or pass raise return self True False try while with yield',
  javascript: 'async await break case catch class const continue default delete do else export extends finally for from function if import in instanceof let new null of return static super switch this throw true false try typeof undefined var void while yield',
  shell: 'if then else fi for do done while case esac function in export set',
  yaml: 'true false null',
  toml: 'true false',
  sql: 'select from where create table index insert into values primary key not null default references on delete cascade',
}
const COMMENT = { python: '#', shell: '#', yaml: '#', toml: '#', javascript: '//', css: null, sql: '--' }

const esc = (s) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')

function tokenRegex(lang) {
  const parts = []
  const c = COMMENT[lang]
  if (c) parts.push(`(?<c>${c.replace(/[/-]/g, '\\$&')}.*$)`)
  if (lang === 'html') parts.push('(?<c><!--.*?-->)', '(?<t></?[\\w-]+)')
  parts.push('(?<s>"(?:\\\\.|[^"\\\\])*"|\'(?:\\\\.|[^\'\\\\])*\'|`(?:\\\\.|[^`\\\\])*`)')
  if (lang === 'python') parts.push('(?<d>@[\\w.]+)')
  parts.push('(?<n>\\b\\d[\\d_.]*\\b)')
  const kw = KEYWORDS[lang]
  if (kw) parts.push(`(?<k>\\b(?:${kw.split(' ').join('|')})\\b)`)
  return new RegExp(parts.join('|'), 'g')
}

const cache = new Map()

export function highlightLines(text, lang) {
  const lines = text.split('\n')
  if (text.endsWith('\n')) lines.pop()
  if (!cache.has(lang)) cache.set(lang, tokenRegex(lang))
  const re = cache.get(lang)
  let inDoc = false

  return lines.map((line) => {
    if (lang === 'python') {
      const quotes = (line.match(/"""|'''/g) ?? []).length
      if (inDoc || quotes) {
        const wasIn = inDoc
        if (quotes % 2 === 1) inDoc = !inDoc
        if (wasIn || quotes) return `<span class="tk-s">${esc(line)}</span>`
      }
    }
    re.lastIndex = 0
    let out = ''
    let last = 0
    for (const m of line.matchAll(re)) {
      const kind = Object.entries(m.groups).find(([, v]) => v !== undefined)?.[0]
      out += esc(line.slice(last, m.index)) + `<span class="tk-${kind}">${esc(m[0])}</span>`
      last = m.index + m[0].length
    }
    return out + esc(line.slice(last))
  })
}

import { structuredPatch } from 'diff'

import { GITLINK_MODE, TREE_MODE, openGit, toHex } from './git.js'
import {
  DATA_EXT,
  MAX_DATA_BYTES,
  MAX_PATCH_LINES,
  MAX_TEXT_BYTES,
  MAX_TREE_FILES,
  buildResolver,
  countLines,
  extractImports,
  extractSymbols,
  langOf,
  parsesSymbols,
  pool,
} from './parse.js'

// Folders never worth walking; FALLBACK_SKIP only applies when the folder has no .gitignore.
const ALWAYS_SKIP = new Set(['.git', 'node_modules'])
const FALLBACK_SKIP = new Set(['.venv', 'venv', '__pycache__', 'dist', 'build', '.next', 'target'])
// Past this many changed lines a diff is counted from the line totals instead of drawn.
const MAX_EDIT_LENGTH = 2000
// Working files up to this size are hashed, so an edit is caught even when the file is too big to
// show; bigger ones are assumed clean.
const MAX_HASH_BYTES = 5_000_000

const decoder = new TextDecoder()

export class LocalError extends Error {}

// Chromium: a directory handle, walked lazily, so ignored folders (node_modules) are never opened.
function handleFolder(root) {
  const dirAt = async (parts) => {
    let dir = root
    for (const part of parts) dir = await dir.getDirectoryHandle(part)
    return dir
  }
  return {
    name: root.name || 'folder',
    async file(path) {
      const parts = path.split('/')
      try {
        return await (await (await dirAt(parts.slice(0, -1))).getFileHandle(parts.at(-1))).getFile()
      } catch {
        return null
      }
    },
    async list(path) {
      try {
        const dir = await dirAt(path.split('/').filter(Boolean))
        const entries = []
        for await (const [name, entry] of dir.entries()) entries.push({ name, dir: entry.kind === 'directory' })
        return entries
      } catch {
        return []
      }
    },
  }
}

// Firefox and Safari: <input webkitdirectory> hands over every file up front as a flat list.
function fileListFolder(fileList) {
  const files = new Map()
  const children = new Map()
  for (const f of fileList) {
    const parts = f.webkitRelativePath.split('/').slice(1)
    files.set(parts.join('/'), f)
    parts.forEach((name, i) => {
      const dir = parts.slice(0, i).join('/')
      if (!children.has(dir)) children.set(dir, new Map())
      children.get(dir).set(name, i < parts.length - 1)
    })
  }
  return {
    name: fileList[0].webkitRelativePath.split('/')[0],
    file: async (path) => files.get(path) ?? null,
    list: async (path) => [...(children.get(path) ?? [])].map(([name, dir]) => ({ name, dir })),
  }
}

// Must run inside a click handler: browsers only open pickers on a user gesture. Cancelling
// rejects with an AbortError.
export function pickFolder() {
  if ('showDirectoryPicker' in window) return window.showDirectoryPicker({ mode: 'read' }).then(handleFolder)
  return new Promise((resolve, reject) => {
    const input = document.createElement('input')
    input.type = 'file'
    input.webkitdirectory = true
    input.onchange = () =>
      input.files.length ? resolve(fileListFolder(input.files)) : reject(new LocalError('That folder has no files.'))
    input.oncancel = () => reject(new DOMException('picker closed', 'AbortError'))
    input.click()
  })
}

const GLOB_PARTS = { '**/': '(?:.*/)?', '**': '.*', '*': '[^/]*', '?': '[^/]' }

// The common subset of .gitignore: globs, anchored paths, dir-only entries and "!" re-includes,
// relative to the folder (`base`) the .gitignore sits in. Character classes are not supported.
function ignoreRules(text, base) {
  return text
    .split('\n')
    .map((line) => line.trim())
    .filter((line) => line && !line.startsWith('#'))
    .map((line) => {
      const negate = line.startsWith('!')
      const pattern = line.replace(/^!/, '').replace(/\/$/, '')
      const body = pattern
        .replace(/^\//, '')
        .split(/(\*\*\/|\*\*|\*|\?)/)
        .map((part) => GLOB_PARTS[part] ?? part.replace(/[.+^${}()|[\]\\]/g, '\\$&'))
        .join('')
      const re = new RegExp(`${pattern.includes('/') ? '^' : '(?:^|/)'}${body}$`)
      return { base, negate, re, dirOnly: line.endsWith('/') }
    })
}

// Like git, the last matching rule wins, and an ignored folder is never entered, so nothing
// inside it can be re-included.
function isIgnored(rules, path, isDir) {
  let ignored = false
  for (const r of rules) {
    if ((isDir || !r.dirOnly) && r.re.test(path.slice(r.base.length))) ignored = !r.negate
  }
  return ignored
}

// What `git ls-files --cached --others --exclude-standard` lists: every file committed at HEAD
// (even if a .gitignore now matches it) plus untracked files nothing ignores. Inside an ignored
// folder that still holds committed files, only those files are kept. The one gap: the global
// excludes file (~/.config/git/ignore) is outside the picked folder, so it can't be applied.
async function listFiles(folder, tracked) {
  const exclude = await folder.file('.git/info/exclude')
  const rootIgnore = await folder.file('.gitignore')
  const skip = rootIgnore ? ALWAYS_SKIP : new Set([...ALWAYS_SKIP, ...FALLBACK_SKIP])
  const trackedDirs = new Set()
  for (const path of tracked.keys()) {
    const parts = path.split('/')
    for (let i = 1; i < parts.length; i++) trackedDirs.add(parts.slice(0, i).join('/'))
  }

  const found = []
  const visit = async (dir, inherited, insideIgnored) => {
    const entries = await folder.list(dir)
    // Like git, never descend into another repository (a nested clone, worktree or submodule).
    if (dir && entries.some((e) => e.name === '.git')) return
    const prefix = dir ? `${dir}/` : ''
    const own = entries.some((e) => e.name === '.gitignore' && !e.dir)
    const rules = own ? [...inherited, ...ignoreRules(await (await folder.file(`${prefix}.gitignore`)).text(), prefix)] : inherited
    await Promise.all(
      entries.map(async (entry) => {
        const path = prefix + entry.name
        if (entry.dir && skip.has(entry.name)) return
        const ignored = insideIgnored || isIgnored(rules, path, entry.dir)
        if (entry.dir && (!ignored || trackedDirs.has(path))) await visit(path, rules, ignored)
        if (!entry.dir && (!ignored || tracked.has(path))) found.push(path)
      }),
    )
  }
  await visit('', exclude ? ignoreRules(await exclude.text(), '') : [], false)
  return found.sort()
}

// The id git gives a file's contents, so a working file can be compared with HEAD unread.
async function blobSha(bytes) {
  const header = new TextEncoder().encode(`blob ${bytes.length}\0`)
  const buffer = new Uint8Array(header.length + bytes.length)
  buffer.set(header)
  buffer.set(bytes, header.length)
  return toHex(new Uint8Array(await crypto.subtle.digest('SHA-1', buffer)))
}

// Binary is decided by content, as git does (a NUL byte), not by extension: the bytes are already
// here, and extensions mislead (.pkl is Pkl config text as often as a Python pickle).
const asText = (bytes) => (bytes.includes(0) ? null : decoder.decode(bytes))

// Blobs are diffed up to MAX_HASH_BYTES, past the display limit, so a big file (a lockfile) still
// gets its line counts; lineDiff falls back to line totals when the diff itself is too large.
async function blobText(git, sha) {
  if (!sha) return ''
  const { data } = await git.read(sha)
  return data.length > MAX_HASH_BYTES ? null : asText(data)
}

// Line diff: add/del counts, GitHub-style hunks, and the new-side line numbers that changed.
function lineDiff(before, after) {
  const result = structuredPatch('', '', before, after, '', '', { context: 3, maxEditLength: MAX_EDIT_LENGTH })
  if (!result) return { add: countLines(after), del: countLines(before), patch: [], lines: [] }

  const diff = { add: 0, del: 0, patch: [], lines: [] }
  result.hunks.forEach((h) => {
    diff.patch.push(`@@ -${h.oldStart},${h.oldLines} +${h.newStart},${h.newLines} @@`, ...h.lines)
    let line = h.newStart
    h.lines.forEach((l) => {
      if (l[0] === '+') {
        diff.add++
        diff.lines.push(line++)
      } else if (l[0] === '-') diff.del++
      else if (l[0] === ' ') line++
    })
  })
  return diff
}

async function diffTrees(git, before, after, prefix = '', out = []) {
  if (before === after) return out
  const a = new Map((before ? await git.tree(before) : []).map((e) => [e.name, e]))
  const b = new Map((after ? await git.tree(after) : []).map((e) => [e.name, e]))
  for (const name of new Set([...a.keys(), ...b.keys()])) {
    const x = a.get(name)
    const y = b.get(name)
    if (x?.sha === y?.sha) continue
    const path = prefix + name
    const xTree = x?.mode === TREE_MODE
    const yTree = y?.mode === TREE_MODE
    if (xTree || yTree) await diffTrees(git, xTree ? x.sha : null, yTree ? y.sha : null, `${path}/`, out)
    const xBlob = x && !xTree && x.mode !== GITLINK_MODE ? x.sha : null
    const yBlob = y && !yTree && y.mode !== GITLINK_MODE ? y.sha : null
    if (xBlob || yBlob) out.push({ path, old: null, before: xBlob, after: yBlob })
  }
  return out
}

// A file deleted and re-added with identical contents in one commit is a rename.
function pairRenames(changes) {
  const removed = new Map(changes.filter((c) => !c.after).map((c) => [c.before, c]))
  const renamed = new Set()
  changes.forEach((c) => {
    const source = !c.before && removed.get(c.after)
    if (!source || renamed.has(source)) return
    renamed.add(source)
    Object.assign(c, { old: source.path, before: source.before })
  })
  return changes.filter((c) => !renamed.has(c))
}

async function toCommitFile(git, change) {
  const before = await blobText(git, change.before)
  const after = await blobText(git, change.after)
  const diff = before === null || after === null ? { add: 0, del: 0, patch: [] } : lineDiff(before, after)
  const patch = DATA_EXT.test(change.path) ? [] : diff.patch
  return {
    path: change.path,
    old: change.old,
    add: diff.add,
    del: diff.del,
    status: !change.before ? 'added' : !change.after ? 'removed' : change.old ? 'renamed' : 'modified',
    patch: patch.slice(0, MAX_PATCH_LINES).join('\n'),
    truncated: patch.length > MAX_PATCH_LINES,
  }
}

// The last `limit` commits on HEAD's first-parent line, oldest first, each diffed against its
// parent. A shallow clone's missing parents end the walk early.
async function readHistory(git, limit, onProgress) {
  const chain = []
  let sha = git.head
  while (sha && chain.length < limit) {
    let commit
    try {
      commit = await git.commit(sha)
    } catch {
      break
    }
    chain.push({ sha, ...commit })
    sha = commit.parents[0] ?? null
  }
  chain.reverse()

  const parentTree = async (c) => {
    try {
      return c.parents[0] ? (await git.commit(c.parents[0])).tree : null
    } catch {
      return null
    }
  }
  const commits = []
  for (const [i, c] of chain.entries()) {
    const changes = pairRenames(await diffTrees(git, await parentTree(c), c.tree))
    commits.push({
      sha: c.sha,
      short: c.sha.slice(0, 7),
      author: c.author,
      date: c.date,
      subject: c.subject,
      files: await pool(changes, 8, (change) => toCommitFile(git, change)),
    })
    onProgress('commit diffs', i + 1, chain.length)
  }
  return { commits, truncated: !!chain[0]?.parents.length }
}

async function flattenTree(git, sha, prefix = '', out = new Map()) {
  for (const entry of await git.tree(sha)) {
    if (entry.mode === TREE_MODE) await flattenTree(git, entry.sha, `${prefix}${entry.name}/`, out)
    else if (entry.mode !== GITLINK_MODE) out.set(prefix + entry.name, entry.sha)
  }
  return out
}

// Working-tree state of one file against HEAD, like `git status`: untracked, clean, or modified
// with the changed lines. Files over MAX_HASH_BYTES are assumed clean; unreadable ones (a broken
// symlink) come back null. Text is only kept for files small enough to show.
async function readWorkingFile(folder, git, headFiles, path) {
  const file = await folder.file(path)
  if (!file) return null
  const bytes = file.size <= MAX_HASH_BYTES ? new Uint8Array(await file.arrayBuffer()) : null
  const shown = file.size <= (DATA_EXT.test(path) ? MAX_DATA_BYTES : MAX_TEXT_BYTES)
  const text = bytes && shown ? asText(bytes) : null
  const entry = { path, bytes: file.size, text, tracked: headFiles.has(path), status: 'untracked', dirtyLines: [] }
  if (!entry.tracked) return entry

  entry.status = 'clean'
  if (!bytes || (await blobSha(bytes)) === headFiles.get(path)) return entry
  entry.status = 'modified'
  const before = await blobText(git, headFiles.get(path))
  if (text !== null && before !== null) entry.dirtyLines = lineDiff(before, text).lines
  return entry
}

export async function loadLocal(folder, { commitLimit = 50, onProgress = () => {} } = {}) {
  onProgress('reading .git', 0, 1)
  const git = await openGit(folder)
  const head = git?.head ? git : null
  const { commits, truncated } = head ? await readHistory(head, commitLimit, onProgress) : { commits: [], truncated: false }
  const headFiles = head ? await flattenTree(head, (await head.commit(head.head)).tree) : new Map()

  onProgress('listing files', 0, 1)
  const paths = await listFiles(folder, headFiles)
  if (!paths.length) throw new LocalError(`${folder.name} has no files to map (everything is ignored or empty).`)
  const kept = paths.slice(0, MAX_TREE_FILES)
  let read = 0
  const working = await pool(kept, 8, async (path) => {
    const entry = await readWorkingFile(folder, head, headFiles, path)
    onProgress('reading files', ++read, kept.length)
    return entry
  })

  const resolver = buildResolver(kept)
  const touched = new Map()
  const authors = new Map()
  commits.forEach((c, idx) =>
    c.files.forEach((f) => {
      if (!touched.has(f.path)) touched.set(f.path, [])
      touched.get(f.path).push(idx)
      if (!authors.has(f.path)) authors.set(f.path, new Set())
      authors.get(f.path).add(c.author)
    }),
  )

  const files = working.filter(Boolean).map((w) => {
    const lang = langOf(w.path)
    return {
      ...w,
      lang,
      loc: countLines(w.text),
      binary: w.text === null,
      symbols: w.text && parsesSymbols(lang) ? extractSymbols(w.text, lang) : [],
      imports: w.text ? extractImports(w.text, lang, w.path, resolver) : [],
      commits: touched.get(w.path) ?? [],
      added: 0,
      deleted: 0,
      authors: [...(authors.get(w.path) ?? [])].sort(),
      blame: [],
    }
  })

  return {
    repo: folder.name,
    head: head ? head.head.slice(0, 7) : '—',
    branch: git ? git.branch : 'no git history',
    generated: new Date().toISOString(),
    source: 'local',
    truncated,
    treeTruncated: paths.length > MAX_TREE_FILES,
    commits,
    files,
  }
}

