function showLoading(text, done = 0, total = 0) {
  $('loading').hidden = false
  $('loading-text').textContent = total ? `${text} ${done}/${total}` : text
  $('loading-bar').style.width = total ? `${(done / total) * 100}%` : '8%'
}

async function completeOAuth() {
  const code = params.get('code')
  const state = params.get('state')
  if (!code || !state) return
  const expected = sessionStorage.getItem(OAUTH_STATE_KEY)
  const returnSearch = sessionStorage.getItem(OAUTH_RETURN_KEY) ?? ''
  sessionStorage.removeItem(OAUTH_STATE_KEY)
  sessionStorage.removeItem(OAUTH_RETURN_KEY)
  history.replaceState(null, '', `${location.pathname}${returnSearch}`)
  params = new URLSearchParams(returnSearch)
  if (state !== expected) await stall('Sign-in could not be verified (state mismatch). Try again.')

  showLoading('signing in with GitHub')
  const res = await fetch(TOKEN_ENDPOINT, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ code }),
  })
  const body = await res.json().catch(() => ({}))
  if (!res.ok || !body.access_token) await stall(`Sign-in failed: ${body.error ?? res.status}`)
  sessionStorage.setItem(TOKEN_KEY, body.access_token)
}

function startOAuth() {
  const state = crypto.randomUUID()
  sessionStorage.setItem(OAUTH_STATE_KEY, state)
  sessionStorage.setItem(OAUTH_RETURN_KEY, location.search)
  const url = new URL('https://github.com/login/oauth/authorize')
  url.searchParams.set('client_id', OAUTH_CLIENT_ID)
  url.searchParams.set('state', state)
  if (OAUTH_SCOPE) url.searchParams.set('scope', OAUTH_SCOPE)
  location.href = url.toString()
}

async function stall(message) {
  $('loading').hidden = false
  $('loading-text').innerHTML = `${esc(message)}<br><br><a class="chip" href="${esc(location.pathname)}">BACK</a>`
  $('loading-bar').style.width = '0%'
  await new Promise(() => {})
}

async function readManifest(url, base) {
  try {
    const res = await fetch(`${url}?t=${Date.now()}`)
    if (!res.ok || !res.headers.get('content-type')?.includes('json')) return []
    return (await res.json()).map((m) => ({ ...m, base }))
  } catch {
    return []
  }
}

// The folder picker only opens on a click, so ?local waits on a button. Closing the picker
// without choosing shows the button again.
async function chooseFolder() {
  $('loading').hidden = false
  $('loading-bar').style.width = '0%'
  $('loading-text').innerHTML =
    'Pick a folder to map. Its files and .git are read inside this tab and never leave your computer.' +
    `<br><br><button id="pick-folder" class="chip">CHOOSE FOLDER</button> <a class="chip" href="${esc(location.pathname)}">BACK</a>`
  for (;;) {
    await new Promise((resolve) => ($('pick-folder').onclick = resolve))
    try {
      return await pickFolder()
    } catch (error) {
      if (error.name !== 'AbortError') throw error
    }
  }
}

async function loadSource() {
  if (params.has('local')) {
    try {
      const folder = await chooseFolder()
      showLoading(`opening ${folder.name}`)
      const doc = await loadLocal(folder, { commitLimit: Number(params.get('n') ?? 50), onProgress: showLoading })
      return { doc, ctx: null, name: doc.repo, manifest: await loadManifests(), publicName: null }
    } catch (error) {
      await stall(error instanceof LocalError ? error.message : `Load failed: ${error.message}`)
    }
  }
  const spec = params.get('gh')
  if (spec) {
    showLoading('connecting to GitHub')
    try {
      const parsed = parseRepoSpec(spec)
      if (params.has('pr')) parsed.pull = Number(params.get('pr'))
      const { doc, ctx } = await loadGithub(parsed, {
        token,
        commitLimit: Number(params.get('n') ?? 50),
        onProgress: showLoading,
      })
      // Without a token GitHub only serves public repos; with one the repo may be private.
      const name = `${doc.owner}/${doc.repo}`
      return { doc, ctx, name, manifest: await loadManifests(), publicName: token ? null : name }
    } catch (error) {
      await stall(error instanceof GithubError ? error.message : `Load failed: ${error.message}`)
    }
  }
  const manifest = await loadManifests()
  if (!manifest.length) await stall('No maps found. Run `npm run scan -- <repo>`, or load a GitHub repo or a local folder from the menu.')
  const requested = params.get('repo')
  const entry = manifest.find((m) => m.name === requested) ?? manifest[0]
  showLoading(`loading ${entry.name}`)
  const doc = await (await fetch(`${entry.base}${entry.name}.json?t=${Date.now()}`)).json()
  // Only the bundled demo maps are known to be public; a scan in local-maps/ may be private.
  return { doc, ctx: null, name: entry.name, manifest, publicName: entry.base === '/demo/' ? entry.label ?? entry.name : null }
}

async function loadManifests() {
  const [local, demo] = await Promise.all([readManifest('/maps/manifest.json', '/maps/'), readManifest('/demo/manifest.json', '/demo/')])
  const names = new Set(local.map((m) => m.name))
  return [...local, ...demo.filter((m) => !names.has(m.name)).sort((a, b) => b.commits - a.commits)]
}

