function resize() {
  renderer.setSize(innerWidth, innerHeight, false)
  composer.setSize(innerWidth, innerHeight)
  labels.setSize(innerWidth, innerHeight)
  outlineMats.forEach((m) => m.resolution.set(innerWidth, innerHeight))
  const aspect = innerWidth / innerHeight
  perspCamera.aspect = aspect
  orthoCamera.left = -ORTHO_HALF * aspect
  orthoCamera.right = ORTHO_HALF * aspect
  applyViewShift()
}

// Width the open code panel covers (matches #panel's min(46vw, 760px)).
const panelWidth = () => (state.selected ? Math.min(innerWidth * 0.46, 760) : 0)

// Slides the projection centre left by half the panel width, so whatever the camera looks at sits
// in the middle of the uncovered area. Eased in frame() to follow the panel's slide.
let viewShift = 0
function applyViewShift() {
  for (const cam of [perspCamera, orthoCamera]) {
    if (viewShift > 0.5) cam.setViewOffset(innerWidth, innerHeight, viewShift, 0, innerWidth, innerHeight)
    else cam.clearViewOffset()
    cam.updateProjectionMatrix()
  }
}
window.addEventListener('resize', resize)

const clock = new THREE.Clock()
function frame() {
  const dt = Math.min(clock.getDelta(), 0.1)
  const time = clock.elapsedTime

  viewHelper.center.copy(controls.target)
  if (viewHelper.animating) {
    viewHelper.update(dt)
    gizmoMoving = true
  } else {
    if (tween) stepTween(dt)
    if (state.fly) stepFly(dt)
    else controls.update()
    if (gizmoMoving) {
      gizmoMoving = false
      // The gizmo's +Y axis is the same top-down map as TOP.
      if (viewDir().y > 0.999 && !camera.isOrthographicCamera) setOrtho(true, { auto: true })
    }
    if (state.orthoAuto && camera.isOrthographicCamera && !tween && controls.getPolarAngle() > 0.15) setOrtho(false)
    const mapMode = camera.isOrthographicCamera && controls.getPolarAngle() < 0.15
    if (mapMode !== state.mapMode) setMapMode(mapMode)
  }

  const pulse = 0.7 + 0.3 * Math.sin(time * 4)
  const ease = Math.min(1, dt * 6)
  const shiftGoal = panelWidth() / 2
  if (Math.abs(shiftGoal - viewShift) > 0.5) {
    viewShift += (shiftGoal - viewShift) * Math.min(1, dt * 12)
    applyViewShift()
  } else if (viewShift !== shiftGoal) {
    viewShift = shiftGoal
    applyViewShift()
  }
  let graphMoved = false
  let layoutMoved = false
  files.forEach((file) => {
    const v = file.vis
    v.h += (v.target - v.h) * Math.min(1, dt * 7)
    v.r += (v.rTarget - v.r) * Math.min(1, dt * 7)
    const goalOff = file.focus.off
    const step = Math.abs(goalOff.x - v.off.x) + Math.abs(goalOff.z - v.off.z) + Math.abs(file.focus.squash - v.squash)
    if (step > 0.001) {
      v.off.x += (goalOff.x - v.off.x) * ease
      v.off.z += (goalOff.z - v.off.z) * ease
      v.squash += (file.focus.squash - v.squash) * ease
      file.tower.group.position.set(file.pos.x + v.off.x, 0, file.pos.z + v.off.z)
      file.strata.group.position.copy(file.tower.group.position)
      file.strata.group.scale.y = v.squash
      layoutMoved = true
    }

    const g = file.tower.group
    g.visible = v.h > 0.03
    g.scale.set(file.pos.w, Math.max(v.h * v.squash, 0.001), file.pos.d)

    const n = file.node.group
    n.visible = v.r > 0.05
    n.scale.setScalar(Math.max(v.r, 0.001))
    const goal = file.graphPos
    if (Math.abs(n.position.x - goal.x) + Math.abs(n.position.y - goal.y) > 0.001) {
      n.position.lerp(new THREE.Vector3(goal.x, goal.y, goal.z), 0.1)
      v.node.copy(n.position)
      graphMoved = true
    }

    const pulsing = state.lens === 'change' && ['modified', 'untracked', 'staged'].includes(file.st) && state.k >= count
    file.mats.forEach(({ material }) => {
      const base = material.userData.base ?? 1
      material.opacity = Math.min(1, base * (pulsing ? pulse : 1))
    })
    if (file === state.selected) file.mats.forEach(({ material, kind }) => kind === 'edge' && (material.opacity = 1))
    if (file === state.hovered) file.mats.forEach(({ material, kind }) => kind === 'edge' && (material.opacity = 1))
  })
  if (graphMoved) updateGraphEdges()
  if (layoutMoved && state.selected) rebuildLinks()

  if (state.selected) {
    const file = state.selected
    const p = currentPosition(file)
    beam.position.set(p.x, state.view === 'graph' ? p.y : 0, p.z)
    selLabel.position.set(p.x, p.y + 1.2, p.z)
    beam.material.opacity = 0.4 + 0.4 * Math.sin(time * 3)
  }

  dust.rotation.y += dt * 0.01
  updateDistricts(ease)
  updateHover(dt)
  composer.render()
  const gizmo = $('gizmo').getBoundingClientRect()
  viewHelper.location.right = innerWidth - gizmo.right
  viewHelper.location.bottom = innerHeight - gizmo.bottom
  // Draw the gizmo over the composed frame instead of clearing it.
  renderer.autoClear = false
  viewHelper.render(renderer)
  renderer.autoClear = true
  labels.render(scene, camera)
  requestAnimationFrame(frame)
}

const FOCUS_COLOR = new THREE.Color('#00f0ff')
const HOT_COLOR = new THREE.Color('#ffffff')
function updateDistricts(ease) {
  const focusDepth = state.focus ? state.focus.split('/').length : 0
  // Deeper folder names appear once the camera is close (or zoomed in, when orthographic).
  const closeUp = (obj) =>
    camera.isOrthographicCamera ? ORTHO_HALF / camera.zoom < city.size * 0.2 : obj.position.distanceTo(camera.position) < city.size * 0.35
  districtLabels.forEach(({ obj, district: d }) => {
    const v = d.vis
    const t = d.target
    v.x += (t.x - v.x) * ease
    v.z += (t.z - v.z) * ease
    v.w += (t.w - v.w) * ease
    v.d += (t.d - v.d) * ease
    obj.position.set(v.x, 0.1, v.z - v.d / 2 + 0.4)
    d.outline.line.position.set(v.x, 0.01, v.z)
    d.outline.line.scale.set(v.w, 1, v.d)

    const inside = inFocus(d.path)
    const ancestor = state.focus.startsWith(`${d.path}/`)
    const hot = d === hotDistrict
    d.outline.mat.color.copy(hot ? HOT_COLOR : d.path === state.focus ? FOCUS_COLOR : d.outline.base)
    d.outline.mat.opacity = OUTLINE_GAIN * (hot || d.path === state.focus ? 1 : inside || ancestor ? 0.8 : 0.8 * GHOST_OPACITY)
    d.label.classList.toggle('hot', hot)
    d.label.style.opacity = inside || ancestor ? '' : String(GHOST_OPACITY + 0.15)
    obj.visible =
      state.view !== 'graph' &&
      (inside ? d.depth <= focusDepth + 1 || closeUp(obj) : d.depth <= 1)
  })
}

resize()
buildButtons()
// Start pulled back so the opening frameView flies in.
camera.position.set(city.size * 0.9, city.size * 0.8, city.size * 1.0).multiplyScalar(1.6)
setView('city')
$('timeline').value = state.k
requestAnimationFrame(frame)

const EXT_LANG = {
  py: 'python',
  js: 'javascript',
  mjs: 'javascript',
  cjs: 'javascript',
  jsx: 'javascript',
  ts: 'typescript',
  tsx: 'typescript',
  html: 'html',
  css: 'css',
  yaml: 'yaml',
  yml: 'yaml',
  toml: 'toml',
  md: 'markdown',
  json: 'json',
  sh: 'shell',
  sql: 'sql',
}
const SCRIPT_LANGS = new Set(['javascript', 'typescript'])
const JS_EXTENSIONS = ['.js', '.mjs', '.cjs', '.jsx', '.ts', '.tsx']

// Shared by the GitHub and local-folder loaders: which files get their text read, and how much.
export const BINARY_EXT = /\.(png|jpe?g|gif|ico|webp|woff2?|ttf|otf|pdf|zip|gz|tar|pkl|xlsx|lock|mp[34]|mov|wasm|so|dylib|bin)$/i
export const DATA_EXT = /\.(json|csv|tsv|jsonl|txt|xml|svg)$/i
export const MAX_TEXT_BYTES = 150_000
export const MAX_DATA_BYTES = 20_000
export const MAX_PATCH_LINES = 150
export const MAX_TREE_FILES = 4000

export const countLines = (text) => (text ? text.split('\n').length - (text.endsWith('\n') ? 1 : 0) : 0)

export function wantsText(entry) {
  if (BINARY_EXT.test(entry.path)) return false
  return entry.size <= (DATA_EXT.test(entry.path) ? MAX_DATA_BYTES : MAX_TEXT_BYTES)
}

// Runs task over items with at most `size` in flight, keeping results in input order.
export async function pool(items, size, task) {
  const queue = [...items.keys()]
  const results = new Array(items.length)
  await Promise.all(
    Array.from({ length: Math.min(size, items.length) }, async () => {
      for (let i = queue.shift(); i !== undefined; i = queue.shift()) results[i] = await task(items[i], i)
    }),
  )
  return results
}

export function langOf(path) {
  const name = path.slice(path.lastIndexOf('/') + 1)
  if (name === 'Dockerfile' || name === 'Justfile' || name === 'Makefile') return 'shell'
  return EXT_LANG[name.slice(name.lastIndexOf('.') + 1).toLowerCase()] ?? 'text'
}

export function parsesSymbols(lang) {
  return lang === 'python' || SCRIPT_LANGS.has(lang)
}

function pythonSymbols(lines) {
  const found = []
  lines.forEach((text, i) => {
    const m = /^(\s*)(?:async\s+)?(class|def)\s+(\w+)/.exec(text)
    if (m) found.push({ indent: m[1].length, kind: m[2], name: m[3], line: i + 1 })
  })
  return found.map((s, i) => {
    const next = found.slice(i + 1).find((n) => n.indent <= s.indent)
    const parent = s.indent > 0 ? found.slice(0, i).reverse().find((p) => p.kind === 'class' && p.indent < s.indent) : null
    return {
      name: s.name,
      kind: s.kind === 'class' ? 'class' : parent ? 'method' : 'function',
      line: s.line,
      end: next ? next.line - 1 : lines.length,
      parent: parent?.name ?? null,
    }
  })
}

function scriptSymbols(lines) {
  const pattern = /^(?:export\s+)?(?:default\s+)?(?:async\s+)?(?:function\s*\*?\s+(\w+)|(class)\s+(\w+)|(?:const|let)\s+(\w+)\s*=)/
  return lines.flatMap((text, i) => {
    const m = pattern.exec(text)
    if (!m) return []
    const kind = m[1] ? 'function' : m[2] ? 'class' : 'const'
    return [{ name: m[1] ?? m[3] ?? m[4], kind, line: i + 1, end: null, parent: null }]
  })
}

export function extractSymbols(text, lang) {
  const lines = text.split('\n')
  if (lang === 'python') return pythonSymbols(lines)
  if (SCRIPT_LANGS.has(lang)) return scriptSymbols(lines)
  return []
}

export function buildResolver(paths) {
  const pathSet = new Set(paths)
  const suffixes = new Map()
  paths
    .filter((p) => p.endsWith('.py'))
    .forEach((p) => {
      const parts = p.slice(0, -3).split('/')
      if (parts.at(-1) === '__init__') parts.pop()
      for (let i = 0; i < parts.length; i++) {
        const key = parts.slice(i).join('.')
        if (!suffixes.has(key)) suffixes.set(key, [])
        suffixes.get(key).push({ path: p, depth: parts.length, rooted: i === 0 || (i === 1 && parts[0] === 'src') })
      }
    })

  const absolute = (dotted) => {
    const hits = suffixes.get(dotted)
    if (!hits) return null
    const multiSegment = dotted.includes('.')
    const eligible = multiSegment ? hits : hits.filter((h) => h.rooted)
    return eligible.sort((a, b) => a.depth - b.depth)[0]?.path ?? null
  }
  const inDir = (dir, dotted) => {
    const base = [dir, ...dotted.split('.')].filter(Boolean).join('/')
    return [`${base}.py`, `${base}/__init__.py`].find((c) => pathSet.has(c)) ?? null
  }
  const script = (fromDir, spec) => {
    const parts = [...fromDir.split('/').filter(Boolean)]
    spec.split('/').forEach((seg) => {
      if (seg === '..') parts.pop()
      else if (seg !== '.') parts.push(seg)
    })
    const base = parts.join('/')
    const candidates = [base, ...JS_EXTENSIONS.map((e) => base + e), ...JS_EXTENSIONS.map((e) => `${base}/index${e}`)]
    return candidates.find((c) => pathSet.has(c)) ?? null
  }
  return { absolute, inDir, script }
}

function pythonImports(text, path, resolver) {
  const dir = path.includes('/') ? path.slice(0, path.lastIndexOf('/')) : ''
  const found = []
  text.split('\n').forEach((line) => {
    const plain = /^\s*import\s+([\w.,\s]+?)(?:\s*#.*)?$/.exec(line)
    if (plain) {
      plain[1].split(',').forEach((part) => found.push(resolver.absolute(part.trim().split(/\s+as\s+/)[0])))
      return
    }
    const from = /^\s*from\s+(\.*)([\w.]*)\s+import\s+\(?([^)#]*)/.exec(line)
    if (!from) return
    const [, dots, module, names] = from
    const members = names.split(',').map((n) => n.trim().split(/\s+as\s+/)[0]).filter(Boolean)
    if (dots) {
      const up = dots.length - 1
      const base = dir.split('/').filter(Boolean)
      const target = base.slice(0, base.length - up).join('/')
      if (module) found.push(resolver.inDir(target, module))
      members.forEach((m) => found.push(resolver.inDir([target, module.replace(/\./g, '/')].filter(Boolean).join('/'), m)))
      if (!module) found.push(resolver.inDir(target, '__init__'))
      return
    }
    found.push(resolver.absolute(module))
    members.forEach((m) => found.push(resolver.absolute(`${module}.${m}`)))
  })
  return found
}

function scriptImports(text, path, resolver) {
  const dir = path.includes('/') ? path.slice(0, path.lastIndexOf('/')) : ''
  const pattern = /(?:from\s+|import\s*\(\s*|require\s*\(\s*|import\s+)['"](\.{1,2}\/[^'"]*)['"]/g
  return [...text.matchAll(pattern)].map((m) => resolver.script(dir, m[1]))
}

export function extractImports(text, lang, path, resolver) {
  let found = []
  if (lang === 'python') found = pythonImports(text, path, resolver)
  else if (SCRIPT_LANGS.has(lang)) found = scriptImports(text, path, resolver)
  return [...new Set(found.filter((p) => p && p !== path))].sort()
}

