.overlay { position: fixed; inset: 0; z-index: 40; background: rgba(2, 5, 12, 0.82); display: flex; align-items: center; justify-content: center; backdrop-filter: blur(4px); padding: 16px; }
/* Capped at the viewport; only .menu-body scrolls, so the title and RESUME stay put. */
.menu-card { width: min(520px, 92vw); max-height: 100%; display: flex; flex-direction: column; border: 1px solid var(--cyan); background: rgba(3, 10, 20, 0.95); padding: 20px 24px; box-shadow: 0 0 40px rgba(0, 240, 255, 0.25); }
.menu-card h1 { margin: 0 0 12px; letter-spacing: 0.3em; color: var(--cyan); font-weight: normal; flex: none; }
.menu-card h2 { margin: 14px 0 6px; font-size: 10px; letter-spacing: 0.2em; color: var(--magenta); font-weight: normal; }
.menu-body { flex: 1; min-height: 0; overflow: auto; }
.menu-foot { flex: none; display: flex; gap: 8px; margin-top: 14px; }
.menu-foot #menu-resume { flex: 1; margin-top: 0; }

#current-repo { display: grid; grid-template-columns: 1fr auto; column-gap: 12px; align-items: center; padding: 10px 12px; border: 1px solid var(--line); background: rgba(0, 240, 255, 0.04); }
#current-name { color: #fff; font-size: 14px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
#current-meta { grid-column: 1; }
#rescan { grid-column: 2; grid-row: 1 / span 2; }
#rescan-status { grid-column: 1 / span 2; }
#rescan-status:empty { display: none; }
.menu-row { display: flex; align-items: center; gap: 12px; }
.menu-row h2 { flex: none; }
.menu-row .field { margin: 8px 0 0; padding: 3px 8px; }

#menu-repos { display: flex; flex-direction: column; }
.repo-row { display: flex; gap: 10px; padding: 5px 8px; color: var(--ice); text-decoration: none; border-left: 2px solid transparent; }
.repo-row:hover { background: rgba(0, 240, 255, 0.1); color: #fff; }
.repo-row.current { border-left-color: var(--cyan); color: var(--cyan); background: rgba(0, 240, 255, 0.06); }
.repo-row .nm { flex: 1; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.repo-row .tag { color: var(--magenta); font-size: 10px; letter-spacing: 0.1em; }

#gh-section, #local-section { margin-top: 14px; }
#gh-section summary, #local-section summary { cursor: pointer; color: var(--magenta); font-size: 10px; letter-spacing: 0.2em; text-transform: uppercase; }
#gh-section summary:hover, #local-section summary:hover { color: #fff; }

.keys-card { width: min(860px, 94vw); }
.keys-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(230px, 1fr)); gap: 0 28px; overflow: auto; }
.keys-grid h2:first-child { margin-top: 0; }
.keys td { padding: 2px 10px 2px 0; vertical-align: top; }
.keys td:first-child { white-space: nowrap; color: var(--cyan); }

#search { position: fixed; top: 18%; left: 50%; transform: translateX(-50%); width: min(560px, 90vw); z-index: 50; background: rgba(3, 10, 20, 0.97); border: 1px solid var(--cyan); box-shadow: 0 0 30px rgba(0, 240, 255, 0.3); }
#search-input { width: 100%; background: none; border: 0; border-bottom: 1px solid var(--line); color: var(--ice); font: 14px var(--mono); padding: 12px; outline: none; }
#search-results .list-row.sel { background: rgba(0, 240, 255, 0.18); }

#menu-repos { display: flex; flex-direction: column; }
a.chip { text-decoration: none; display: block; }
/* Feedback is a link to GitHub, so keep it quieter than the controls. */
#hud-views a.feedback { text-align: left; opacity: 0.7; font-size: 10px; }
#hud-views a.feedback:hover { opacity: 1; }
.menu-foot a.feedback { display: flex; align-items: center; }

#loading { position: fixed; inset: 0; z-index: 60; background: var(--bg); display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 18px; }
#loading[hidden] { display: none; }
#loading-text { color: var(--ice); text-align: center; max-width: 520px; }
#loading-track { width: min(420px, 80vw); height: 3px; background: rgba(0, 240, 255, 0.15); }
#loading-bar { height: 100%; width: 8%; background: var(--cyan); box-shadow: 0 0 10px var(--cyan); transition: width 0.15s; }
.field { width: 100%; margin-top: 6px; background: rgba(0, 240, 255, 0.05); border: 1px solid var(--line); color: var(--ice); font: inherit; padding: 6px 8px; outline: none; }
.field:focus { border-color: var(--cyan); }
.note { margin-top: 6px; font-size: 10px; }

import { execFile } from 'node:child_process'
import { existsSync, readFileSync } from 'node:fs'
import { basename, resolve } from 'node:path'
import { defineConfig, loadEnv } from 'vite'

const { version } = JSON.parse(readFileSync(resolve(import.meta.dirname, 'package.json'), 'utf8'))
const scanner = resolve(import.meta.dirname, '../scan/scan.py')
const outDir = resolve(import.meta.dirname, 'local-maps')

const functionHandlers = {
  '/.netlify/functions/github-token': () => import('./netlify/functions/github-token.mjs'),
}

const netlifyFunctions = () => ({
  name: 'netlify-functions-dev',
  configureServer(server) {
    server.middlewares.use(async (req, res, next) => {
      const load = functionHandlers[new URL(req.url, 'http://localhost').pathname]
      if (!load) return next()
      const chunks = []
      for await (const chunk of req) chunks.push(chunk)
      const body = chunks.length ? Buffer.concat(chunks) : undefined
      const request = new Request(`http://${req.headers.host}${req.url}`, {
        method: req.method,
        headers: req.headers,
        body: req.method === 'GET' || req.method === 'HEAD' ? undefined : body,
      })
      const response = await (await load()).default(request)
      res.statusCode = response.status
      response.headers.forEach((value, key) => res.setHeader(key, value))
      res.end(Buffer.from(await response.arrayBuffer()))
    })
  },
})

const rescan = () => ({
  name: 'codemap-rescan',
  configureServer(server) {
    server.middlewares.use('/maps/', (req, res, next) => {
      const file = resolve(outDir, basename(new URL(req.url, 'http://localhost').pathname))
      if (!existsSync(file)) return next()
      res.setHeader('content-type', 'application/json')
      res.end(readFileSync(file))
    })
    server.middlewares.use('/api/rescan', (req, res) => {
      const name = new URL(req.url, 'http://localhost').searchParams.get('repo')
      const manifestPath = resolve(outDir, 'manifest.json')
      const known = existsSync(manifestPath) ? JSON.parse(readFileSync(manifestPath, 'utf8')) : []
      const entry = known.find((m) => m.name === name)
      if (!entry) {
        res.statusCode = 404
        res.end(JSON.stringify({ ok: false, message: `unknown repo ${name}` }))
        return
      }
      execFile('python3', ['-I', scanner, entry.path, '--out-dir', outDir], (error, stdout, stderr) => {
        res.setHeader('content-type', 'application/json')
        res.statusCode = error ? 500 : 200
        res.end(JSON.stringify({ ok: !error, message: (error ? stderr : stdout).trim() }))
      })
    })
  },
})

export default defineConfig(({ mode }) => {
  Object.assign(process.env, loadEnv(mode, import.meta.dirname, ''))
  return { define: { __APP_VERSION__: JSON.stringify(version) }, plugins: [rescan(), netlifyFunctions()], server: { host: '127.0.0.1', port: 5179 } }
})
